                                                                                                                                                                                                     
  CREATE TABLE "TENANT_BASE"                                                                                                                                                              
   (	"BASE_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 2 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                          
	"CREATION_DATE" DATE,                                                                                                                                                                               
	"UPDATED_BY" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                          
	"UPDATE_DATE" DATE,                                                                                                                                                                                 
	"REMARK" NVARCHAR2(512),                                                                                                                                                                            
	"DEL_FLAG" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                        
	"NAME" NVARCHAR2(32) NOT NULL ENABLE,                                                                                                                                                               
	"IS_ENABLE" NUMBER NOT NULL ENABLE,                                                                                                                                                                 
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                 
	"SYSTEM_CODE" NVARCHAR2(32),                                                                                                                                                                        
	"ADDRESS" VARCHAR2(256),                                                                                                                                                                            
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                       
	 PRIMARY KEY ("BASE_ID")                                                                                                                                                                            
  USING INDEX  ENABLE                                                                                                                                                                                
   ) ;                                                                                                                                                                                               

